import{_ as i,a0 as p,w as o,s as d,ao as a,I as l,x as n,a1 as u,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"每日 Ubuntu 小技巧：怎樣在Ubuntu升級新的 Linux Kernel 3.12.7 | LCTT x X-CMD","titleTemplate":false,"description":"每日 Ubuntu 小技巧：怎樣在Ubuntu升級新的 Linux Kernel 3.12.7 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日 Ubuntu 小技巧：怎樣在Ubuntu升級新的 Linux Kernel 3.12.7 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日 Ubuntu 小技巧：怎樣在Ubuntu升級新的 Linux Kernel 3.12.7 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Daily Ubuntu Tips – Linux Kernel 3.12.7 Released – Here’s How To Upgrade In Ubuntu","title":"每日 Ubuntu 小技巧：怎樣在Ubuntu升級新的 Linux Kernel 3.12.7","tag":"201403","desc":""},"relativePath":"201403/Daily Ubuntu Tips – Linux Kernel 3.12.7 Released – Here’s How To Upgrade In Ubuntu.md","filePath":"[post].md"}'),s={name:"201403/Daily Ubuntu Tips – Linux Kernel 3.12.7 Released – Here’s How To Upgrade In Ubuntu.md"};function b(m,e,x,_,g,k){const t=p("Link");return o(),d("div",null,[e[14]||(e[14]=a('<h1 id="每日-ubuntu-小技巧-怎樣在ubuntu升級新的-linux-kernel-3-12-7" tabindex="-1">每日 Ubuntu 小技巧：怎樣在Ubuntu升級新的 Linux Kernel 3.12.7 <a class="header-anchor" href="#每日-ubuntu-小技巧-怎樣在ubuntu升級新的-linux-kernel-3-12-7" aria-label="Permalink to “每日 Ubuntu 小技巧：怎樣在Ubuntu升級新的 Linux Kernel 3.12.7”">​</a></h1><p>Linux Kernel 版本3.12.7主線已經發布了，而這篇簡短教程將會向你展示怎樣簡單地在 Ubuntu 中升級。如果你正好運行 Ubuntu 13.10 或者更低版本，還碰巧你的系統還不是安裝最新的內核，讀完吧。</p><p>Linux Kernel 是 linux 操作系統的核心，包括了 Ubuntu。內核使 Ubuntu 可以與系統硬件（內存，CPU，設備等等）通信。內核管理資源並掌管你機器設備的所有重要部分。</p><p>沒有 Linux Kernel， Ubuntu 只是一串幻想應用而不能連接硬件或者你機器所有的重要部分。這就是為什麼Linux Kernel 如此的重要。</p><h3 id="為什麼升級你的-ubuntu-kernel" tabindex="-1">為什麼升級你的 Ubuntu Kernel? <a class="header-anchor" href="#為什麼升級你的-ubuntu-kernel" aria-label="Permalink to “為什麼升級你的 Ubuntu Kernel?”">​</a></h3><p>在升級你的系統內核之前，第一件需要知道的事情就是升級可能會破壞你的系統，使它無法使用。事實上，並不推薦你自己升級內核。Ubuntu 的總公司 Canonical 在 Ubuntu 內核升級上做得很好。</p><p>在新版本發佈之前，他們測試並且確定內核的安裝是兼容的。所以，如果你的設備工作良好，沒有問題，你應該保持現有內核，不要升級。</p><p>另一方面，如果 Ubuntu 不能識別所有系統的元件或者你的設備功能不正確，升級 Linux kernel 也許會有幫助。</p><p>這是因為新的內核為你的新機器增加了新的驅動和功能。如果現在安裝的內核不支持機器上的某些功能，你應該升級一下。</p>',9)),l("p",null,[e[1]||(e[1]=n("更多關於內核3.12.7，",-1)),u(t,{href:"https://www.kernel.org/pub/linux/kernel/v3.x/ChangeLog-3.12.7"},{default:r(()=>[...e[0]||(e[0]=[n("點這裏閲讀更新日誌",-1)])]),_:1}),e[2]||(e[2]=n("。",-1))]),e[15]||(e[15]=a(`<h3 id="現在升級-linux-kernel" tabindex="-1">現在升級 Linux Kernel <a class="header-anchor" href="#現在升級-linux-kernel" aria-label="Permalink to “現在升級 Linux Kernel”">​</a></h3><p>要想升級你的內核，運行下列命令來升級所有安裝包和現存內核。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade &amp;&amp; sudo apt-get autoremove
</code></pre><p>升級完成後，重啓你的設備。在安裝完系統包和內核後重啓機器是一個好習慣。這樣做是為了讓新的內核能夠被應用。</p><p>接下來，運行下列命令來下載 Linux Kernel 3.12.7</p><h4 id="_32位設備-運行下列命令" tabindex="-1">32位設備，運行下列命令 <a class="header-anchor" href="#_32位設備-運行下列命令" aria-label="Permalink to “32位設備，運行下列命令”">​</a></h4><pre><code>cd /tmp &amp;&amp; wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-headers-3.12.7-031207-generic_3.12.7-031207.201401091657_i386.deb http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-headers-3.12.7-031207_3.12.7-031207.201401091657_all.deb http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-image-3.12.7-031207-generic_3.12.7-031207.201401091657_i386.deb
</code></pre><h4 id="_64位設備-運行下列命令" tabindex="-1">64位設備，運行下列命令 <a class="header-anchor" href="#_64位設備-運行下列命令" aria-label="Permalink to “64位設備，運行下列命令”">​</a></h4><pre><code>cd /tmp &amp;&amp; wget http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-headers-3.12.7-031207-generic_3.12.7-031207.201401091657_amd64.deb http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-headers-3.12.7-031207_3.12.7-031207.201401091657_all.deb http://kernel.ubuntu.com/~kernel-ppa/mainline/v3.12.7-trusty/linux-image-3.12.7-031207-generic_3.12.7-031207.201401091657_amd64.deb
</code></pre><p>下載你的系統對應版本後，運行下列命令</p><pre><code>sudo dpkg -i *.deb
</code></pre><p>安裝完成後，重啓你的設備，如果一切都按照上面描述一樣進展順利，你的系統應該擁有了最新穩定的內核版本。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/linuxkernel3127.jpg" alt=""></p><p>卸載內核3.12.7版本，使用下列命令</p><pre><code>sudo apt-get remove linux-headers-3.12.7-* linux-image-3.13.7-*
</code></pre><p>好好享受吧！</p><hr>`,17)),l("p",null,[e[4]||(e[4]=n("via: ",-1)),u(t,{href:"http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-linux-kernel-3-12-7-released-heres-how-to-upgrade-in-ubuntu/"},{default:r(()=>[...e[3]||(e[3]=[n("http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-linux-kernel-3-12-7-released-heres-how-to-upgrade-in-ubuntu/",-1)])]),_:1})]),l("p",null,[e[7]||(e[7]=n("譯者：",-1)),u(t,{href:"http://blog.csdn.net/Vic___"},{default:r(()=>[...e[5]||(e[5]=[n("Vic___",-1)])]),_:1}),e[8]||(e[8]=n(" 校對：",-1)),u(t,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...e[6]||(e[6]=[n("Caroline",-1)])]),_:1})]),l("p",null,[e[11]||(e[11]=n("本文由 ",-1)),u(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[9]||(e[9]=[n("LCTT",-1)])]),_:1}),e[12]||(e[12]=n(" 原創翻譯，",-1)),u(t,{href:"http://linux.cn/"},{default:r(()=>[...e[10]||(e[10]=[n("Linux中國",-1)])]),_:1}),e[13]||(e[13]=n(" 榮譽推出",-1))])])}const L=i(s,[["render",b]]);export{h as __pageData,L as default};
